create table if not exists alert_event (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  source varchar(64) not null,  source_event_id varchar(256),  severity varchar(32) not null default 'info',  title varchar(512) not null,  description text,  asset_id varchar(64),  entity_type varchar(64),  entity_name varchar(256),  labels jsonb not null default '{}'::jsonb,  starts_at timestamptz not null default now(),  ends_at timestamptz,  status varchar(32) not null default 'open',  raw_payload jsonb not null default '{}'::jsonb,  fingerprint varchar(512) not null,  aggregation_key varchar(512),  updated_at timestamptz not null default now(),  created_at timestamptz not null default now());create table if not exists incident (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  title varchar(512) not null,  summary text,  severity varchar(32) not null default 'low',  status varchar(32) not null default 'open',  source varchar(64) not null default 'system',  primary_asset_id varchar(64),  suspected_root_cause text,  confidence numeric(5,4),  impact_score numeric(10,4) not null default 0,  aggregation_key varchar(512),  last_seen_at timestamptz,  alert_count integer not null default 0,  started_at timestamptz not null default now(),  detected_at timestamptz not null default now(),  resolved_at timestamptz,  owner_user_id varchar(64),  created_at timestamptz not null default now(),  updated_at timestamptz not null default now());create table if not exists incident_event (  id varchar(64) primary key,  incident_id varchar(64) not null references incident(id) on delete cascade,  event_type varchar(64) not null,  event_id varchar(64) not null,  relation_type varchar(64) not null default 'related',  occurred_at timestamptz not null default now());create table if not exists incident_timeline (  id varchar(64) primary key,  incident_id varchar(64) not null references incident(id) on delete cascade,  event_time timestamptz not null,  event_type varchar(64) not null,  title varchar(512) not null,  description text,  source varchar(64) not null default 'system',  payload jsonb not null default '{}'::jsonb);alter table alert_event add column if not exists updated_at timestamptz;alter table alert_event add column if not exists aggregation_key varchar(512);alter table incident add column if not exists aggregation_key varchar(512);alter table incident add column if not exists last_seen_at timestamptz;alter table incident add column if not exists alert_count integer not null default 0;create index if not exists idx_alert_event_tenant_starts on alert_event(tenant_id, starts_at desc);create index if not exists idx_alert_event_fingerprint on alert_event(tenant_id, fingerprint);create index if not exists idx_alert_event_tenant_source_status on alert_event(tenant_id, source, status);create index if not exists idx_alert_event_tenant_updated_at on alert_event(tenant_id, updated_at desc);create index if not exists idx_alert_event_tenant_ends_at on alert_event(tenant_id, ends_at desc);create index if not exists idx_alert_event_tenant_aggregation_key on alert_event(tenant_id, aggregation_key);create index if not exists idx_alert_event_tenant_status_aggregation_key on alert_event(tenant_id, status, aggregation_key);create unique index if not exists uq_alert_event_tenant_source_source_event_id  on alert_event(tenant_id, source, source_event_id) where source_event_id is not null;create index if not exists idx_incident_tenant_started on incident(tenant_id, started_at desc);create index if not exists idx_incident_tenant_status_started on incident(tenant_id, status, started_at desc);create index if not exists idx_incident_tenant_aggregation_key on incident(tenant_id, aggregation_key);create index if not exists idx_incident_tenant_aggregation_key_status on incident(tenant_id, aggregation_key, status);create unique index if not exists uq_incident_active_aggregation_key  on incident(tenant_id, aggregation_key)  where aggregation_key is not null    and status in ('open', 'investigating', 'mitigating');create index if not exists idx_incident_event_incident on incident_event(incident_id);create unique index if not exists uq_incident_event_incident_event  on incident_event(incident_id, event_type, event_id);create unique index if not exists uq_incident_event_alert_once  on incident_event(event_type, event_id) where event_type = 'alert';create index if not exists idx_incident_timeline_incident_time  on incident_timeline(incident_id, event_time desc);
